/// <summary>
/// This class extends the logic of creating vendor vouchers to support split payment mandatory rule functionality.
/// </summary>
[ExtensionOf(classStr(VendVoucher))]
public final class METVendVoucher_Extension
{
}

Method.Source:
    protected boolean checkInvoice(VendAccount _vendAccount, InvoiceId _invoiceId, TransDate _transDate)
    {
        boolean ret;

        CurrencyCode currencyCode = this.currencyCode;
        Amount invoiceAmount = abs(this.parmAmountCur());
        date invoiceDate = this.parmDocumentDate();

        ret = next checkInvoice(_vendAccount, _invoiceId, _transDate);

        if(VendParameters::find().METInvoiceValidation)
        {
            ret = this.metCheckInvoice(_vendAccount, _invoiceId, invoiceDate, currencyCode, invoiceAmount);
        }

        return ret;
    }

    private boolean metCheckInvoice(VendAccount _vendAccount, InvoiceId _invoiceId, TransDate _transDate, Currencycode _currencyCode, Amount _invoiceAmount)
    {
        VendInvoiceJour vendInvoiceJour;
        boolean ret = true;

        
        select firstonly InvoiceAmount from vendInvoiceJour  // Check invoice, vendor, currency and amount
                    where vendInvoiceJour.InvoiceId == _invoiceId
                        && vendInvoiceJour.InvoiceAccount == _vendAccount
                        && vendInvoiceJour.CurrencyCode == _currencyCode
                        && vendInvoiceJour.InvoiceAmount == _invoiceAmount;

        if(vendInvoiceJour.InvoiceAmount != 0)
        {
            ret =  checkFailed(strFmt("@MET:METInvoiceWithAmountAlreadyUsedForVendor", _invoiceId, vendInvoiceJour.InvoiceAmount, date2StrUsr(_transDate, DateFlags::FormatAll),                                       _vendAccount));
        }

        if(ret)
        {
            select InvoiceDate , InvoiceAmount from vendInvoiceJour //Check invoice, date, currency and amount
                        where vendInvoiceJour.InvoiceId == _invoiceId
                            && vendInvoiceJour.InvoiceDate == _transDate
                            && vendInvoiceJour.CurrencyCode == _currencyCode
                            && vendInvoiceJour.InvoiceAmount == _invoiceAmount;

            if(vendInvoiceJour.InvoiceAmount != 0)
            {
                ret =  checkFailed(strFmt("@MET:METInvoiceWithmountAlreadyUsedOnDate", _invoiceId, vendInvoiceJour.InvoiceAmount, date2StrUsr(_transDate, DateFlags::FormatAll)));
            }
        }


        return ret;
    }

    /// <summary>
    ///     Populate <c>VendInvoiceJour</c>.
    ///     MPJ_21593 SVR document DCP 12/05/2022
    /// </summary>
    /// <param name = "_vendTrans">
    ///     The vendor transaction used to initialize <c>VendInvoiceJour</c>.
    /// </param>
    /// <returns>
    ///     The original vend invoice journal record ID.
    /// </returns>
    protected RefRecId populateVendInvoiceJour(CustVendTrans _vendTrans)
    {
        LedgerJournalTrans  metLedgerJournalTrans;
        RefRecId            metOrigVendInvoiceJourRecId;
        
        metOrigVendInvoiceJourRecId = next populateVendInvoiceJour(_vendTrans);

        if (common.TableId == tableNum(LedgerJournalTrans))
        {
            metLedgerJournalTrans = common;
        
            vendInvoiceJour.METALMSupplierVolumetricRebateNumber = metLedgerJournalTrans.METALMSupplierVolumetricRebateNumber;
        }
    
        return metOrigVendInvoiceJourRecId;
    }
